1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_main.c
3	 *
4	 * Xiaozhi AI Voice App — Phase 2 entry point.
5	 *
6	 * Full dialog: OTA -> wss connect -> hello -> listen start -> mic capture
7	 * (Opus uplink) -> listen stop -> receive stt/tts -> TTS Opus playback.
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 ****************************************************************************/
11	
12	#include <nuttx/config.h>
13	
14	#include <stdio.h>
15	#include <string.h>
16	#include <stdlib.h>
17	#include <unistd.h>
18	#include <pthread.h>
19	#include <semaphore.h>
20	
21	#include <netutils/cJSON.h>
22	
23	#include "xiaozhi_ota.h"
24	#include "xiaozhi_ws.h"
25	#include "xiaozhi_audio.h"
26	
27	/****************************************************************************
28	 * Pre-processor Definitions
29	 ****************************************************************************/
30	
31	#define XIAOZHI_MAC_DEFAULT "6b:48:a8:95:7d:e1"
32	#define XZ_OPUS_MAX        400
33	#define XZ_DIALOG_SECONDS  4      /* capture duration per turn */
34	
35	/****************************************************************************
36	 * Private Types
37	 ****************************************************************************/
38	
39	struct xiaozhi_app_s
40	{
41	  struct xiaozhi_ws_s    ws;
42	  struct xiaozhi_audio_s audio;
43	  char session_id[16];
44	  bool ws_connected;
45	  bool got_stt;
46	  bool tts_playing;
47	  int  tts_sentences;
48	};
49	
50	/* Context shared with the uplink worker thread. */
51	struct uplink_ctx_s
52	{
53	  struct xiaozhi_app_s *app;
54	  int seconds;
55	};
56	
57	/****************************************************************************
58	 * Private Data
59	 ****************************************************************************/
60	
61	static struct xiaozhi_app_s g_app;
62	
63	/****************************************************************************
64	 * Private Functions
65	 ****************************************************************************/
66	
67	/* Send a JSON text frame built with cJSON. */
68	static int send_json(struct xiaozhi_app_s *app, cJSON *root)
69	{
70	  char *json = cJSON_PrintUnformatted(root);
71	  if (json == NULL)
72	    {
73	      return -ENOMEM;
74	    }
75	
76	  int ret = xiaozhi_ws_send_text(&app->ws, json, strlen(json));
77	  free(json);
78	  return ret;
79	}
80	
81	/* Uplink worker: capture Opus frames and send as binary frames for the
82	 * given number of seconds.
83	 */
84	static void *uplink_worker(void *arg)
85	{
86	  struct uplink_ctx_s *uc = arg;
87	  struct xiaozhi_app_s *app = uc->app;
88	  uint8_t frame[XZ_OPUS_MAX];
89	  int frames = 0;
90	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
91	
92	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
93	         target_frames, uc->seconds);
94	
95	  while (frames < target_frames && app->ws_connected)
96	    {
97	      ssize_t n = xiaozhi_audio_read_opus(&app->audio, frame, sizeof(frame));
98	      if (n < 0)
99	        {
100	          printf("[xiaozhi] uplink read err: %zd\n", n);
101	          break;
102	        }
103	
104	      if (n > 0)
105	        {
106	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
107	          if (ret != 0)
108	            {
109	              printf("[xiaozhi] uplink send err: %d\n", ret);
110	              break;
111	            }
112	
113	          frames++;
114	        }
115	    }
116	
117	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
118	  return NULL;
119	}
120	
121	/* Receive worker: parse server messages and feed TTS audio to the player.
122	 * Runs until ws is closed or a stop condition.
123	 */
124	static void recv_loop(struct xiaozhi_app_s *app, int max_ms)
125	{
126	  int waited = 0;
127	
128	  while (app->ws_connected && waited < max_ms)
129	    {
130	      const uint8_t *payload;
131	      size_t plen;
132	      bool is_binary;
133	      int ret;
134	
135	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
136	      if (ret != 0)
137	        {
138	          app->ws_connected = false;
139	          break;
140	        }
141	
142	      if (is_binary)
143	        {
144	          /* Server TTS Opus frame -> feed to player. */
145	          if (app->tts_playing)
146	            {
147	              xiaozhi_audio_write_opus(&app->audio, payload, plen);
148	            }
149	
150	          waited += 60;
151	          continue;
152	        }
153	
154	      /* Text frame: parse JSON. */
155	      {
156	        char *json = malloc(plen + 1);
157	        if (json == NULL)
158	          {
159	            continue;
160	          }
161	
162	        memcpy(json, payload, plen);
163	        json[plen] = '\0';
164	
165	        cJSON *root = cJSON_Parse(json);
166	        if (root != NULL)
167	          {
168	            cJSON *type = cJSON_GetObjectItem(root, "type");
169	            const char *tstr = cJSON_IsString(type) ?
170	              type->valuestring : "";
171	
172	            if (strcmp(tstr, "stt") == 0)
173	              {
174	                cJSON *text = cJSON_GetObjectItem(root, "text");
175	                printf("[xiaozhi] <<< STT: \"%s\"\n",
176	                       text ? text->valuestring : "?");
177	                app->got_stt = true;
178	              }
179	            else if (strcmp(tstr, "llm") == 0)
180	              {
181	                cJSON *text = cJSON_GetObjectItem(root, "text");
182	                printf("[xiaozhi] <<< LLM: \"%s\" (%s)\n",
183	                       text ? text->valuestring : "?",
184	                       cJSON_IsString(cJSON_GetObjectItem(root, "emotion")) ?
185	                       cJSON_GetObjectItem(root, "emotion")->valuestring :
186	                       "-");
187	              }
188	            else if (strcmp(tstr, "tts") == 0)
189	              {
190	                cJSON *state = cJSON_GetObjectItem(root, "state");
191	                const char *sstr = cJSON_IsString(state) ?
192	                  state->valuestring : "";
193	
194	                if (strcmp(sstr, "start") == 0)
195	                  {
196	                    app->tts_playing = true;
197	                    xiaozhi_audio_start_playback(&app->audio);
198	                    printf("[xiaozhi] <<< TTS start\n");
199	                  }
200	                else if (strcmp(sstr, "stop") == 0)
201	                  {
202	                    app->tts_playing = false;
203	                    printf("[xiaozhi] <<< TTS stop\n");
204	                    xiaozhi_audio_stop_playback(&app->audio);
205	                    break;   /* end of this turn */
206	                  }
207	                else if (strcmp(sstr, "sentence_start") == 0)
208	                  {
209	                    cJSON *text = cJSON_GetObjectItem(root, "text");
210	                    printf("[xiaozhi] <<< TTS: \"%s\"\n",
211	                           text ? text->valuestring : "?");
212	                    app->tts_sentences++;
213	                  }
214	              }
215	            else if (strcmp(tstr, "goodbye") == 0)
216	              {
217	                printf("[xiaozhi] <<< goodbye\n");
218	                app->ws_connected = false;
219	                cJSON_Delete(root);
220	                free(json);
221	                break;
222	              }
223	            else if (strcmp(tstr, "hello") == 0)
224	              {
225	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
226	                if (cJSON_IsString(sid))
227	                  {
228	                    strncpy(app->session_id, sid->valuestring,
229	                            sizeof(app->session_id) - 1);
230	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
231	                           app->session_id);
232	                  }
233	              }
234	            else
235	              {
236	                printf("[xiaozhi] <<< %s\n", tstr);
237	              }
238	
239	            cJSON_Delete(root);
240	          }
241	        else
242	          {
243	            printf("[xiaozhi] <<< (parse err) %.*s\n",
244	                   (int)plen, (const char *)payload);
245	          }
246	
247	        free(json);
248	      }
249	
250	      waited += 60;
251	    }
252	}
