257	
258	int main(int argc, FAR char *argv[])
259	{
260	  struct xiaozhi_ota_config_s ota;
261	  const char *mac = XIAOZHI_MAC_DEFAULT;
262	  char client_id[40];
263	  int ret;
264	  struct uplink_ctx_s uc;
265	
266	  memset(&g_app, 0, sizeof(g_app));
267	
268	  printf("[xiaozhi] === Phase 2: full dialog ===\n");
269	
270	  snprintf(client_id, sizeof(client_id),
271	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
272	
273	  /* Init audio subsystem. */
274	  ret = xiaozhi_audio_init(&g_app.audio);
275	  if (ret != 0)
276	    {
277	      printf("[xiaozhi] audio init failed: %d\n", ret);
278	      return 1;
279	    }
280	
281	  /* Step 1: OTA. */
282	  printf("[xiaozhi] step 1: OTA\n");
283	  ret = xiaozhi_ota_fetch(mac, &ota);
284	  if (ret != 0)
285	    {
286	      printf("[xiaozhi] OTA failed: %d\n", ret);
287	      return 1;
288	    }
289	
290	  /* Step 2: wss connect + hello. */
291	  printf("[xiaozhi] step 2: wss connect\n");
292	  ret = xiaozhi_ws_connect(&g_app.ws, ota.ws_url, ota.ws_token, mac,
293	                           client_id);
294	  if (ret != 0)
295	    {
296	      printf("[xiaozhi] ws connect failed: %d\n", ret);
297	      return 1;
298	    }
299	
300	  g_app.ws_connected = true;
301	
302	  /* Wait for hello response to get session_id. */
303	  printf("[xiaozhi] step 3: wait hello\n");
304	  recv_loop(&g_app, 5000);   /* up to 5s for hello */
305	  if (g_app.session_id[0] == '\0')
306	    {
307	      printf("[xiaozhi] no session_id, abort\n");
308	      goto out;
309	    }
310	
311	  /* Step 4: listen start + capture + listen stop. */
312	  printf("[xiaozhi] step 4: listen start + capture\n");
313	  {
314	    cJSON *hello = cJSON_CreateObject();
315	    cJSON_AddStringToObject(hello, "session_id", g_app.session_id);
316	    cJSON_AddStringToObject(hello, "type", "listen");
317	    cJSON_AddStringToObject(hello, "state", "start");
318	    cJSON_AddStringToObject(hello, "mode", "manual");
319	    send_json(&g_app, hello);
320	    cJSON_Delete(hello);
321	    printf("[xiaozhi] >>> listen start\n");
322	  }
323	
324	  /* Start capture and run uplink worker for N seconds. */
325	  ret = xiaozhi_audio_start_capture(&g_app.audio);
326	  if (ret != 0)
327	    {
328	      printf("[xiaozhi] capture start failed: %d\n", ret);
329	      goto out;
330	    }
331	
332	  /* Drain any incoming binary/text while capturing by spawning uplink in
333	   * a thread and looping recv here too. Simplest: run uplink synchronously
334	   * (block on capture), the server tolerates a gap before listen stop.
335	   */
336	  uc.app = &g_app;
337	  uc.seconds = XZ_DIALOG_SECONDS;
338	  uplink_worker(&uc);
339	
340	  xiaozhi_audio_stop_capture(&g_app.audio);
341	
342	  /* listen stop. */
343	  {
344	    cJSON *stop = cJSON_CreateObject();
345	    cJSON_AddStringToObject(stop, "session_id", g_app.session_id);
346	    cJSON_AddStringToObject(stop, "type", "listen");
347	    cJSON_AddStringToObject(stop, "state", "stop");
348	    send_json(&g_app, stop);
349	    cJSON_Delete(stop);
350	    printf("[xiaozhi] >>> listen stop\n");
351	  }
352	
353	  /* Step 5: receive stt + tts + playback (up to 20s). */
354	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
355	  recv_loop(&g_app, 20000);
356	
357	out:
358	  if (g_app.tts_playing)
359	    {
360	      xiaozhi_audio_stop_playback(&g_app.audio);
361	    }
362	
363	  xiaozhi_audio_deinit(&g_app.audio);
364	  xiaozhi_ws_close(&g_app.ws);
365	
366	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
367	         g_app.got_stt ? "yes" : "no", g_app.tts_sentences);
368	  return 0;
369	}
