1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_ws.c
3	 *
4	 * A lightweight WebSocket-over-TLS (wss) client.
5	 *   - TLS layer: mbedtls (pattern borrowed from packages/demos/mimo)
6	 *   - WebSocket framing: RFC 6455
7	 *
8	 * Supports the subset needed by the xiaozhi protocol:
9	 *   - client->server text(0x1) and binary(0x2) frames, masked
10	 *   - server->client text/binary/close frames, unmasked
11	 *   - payload lengths up to 65535 (16-bit length); 64-bit length not needed
12	 *     here (Opus frames and JSON messages are short)
13	 *
14	 * SPDX-License-Identifier: Apache-2.0
15	 ****************************************************************************/
16	
17	#include <nuttx/config.h>
18	
19	#include <stdio.h>
20	#include <string.h>
21	#include <stdlib.h>
22	#include <errno.h>
23	#include <unistd.h>
24	#include <netdb.h>
25	#include <netinet/in.h>
26	#include <arpa/inet.h>
27	#include <sys/socket.h>
28	
29	#include "xiaozhi_ws.h"
30	
31	/****************************************************************************
32	 * Pre-processor Definitions
33	 ****************************************************************************/
34	
35	#define WS_RXBUF_SIZE  4096
36	
37	/* WebSocket opcodes */
38	#define WS_OPCODE_CONTINUATION 0x0
39	#define WS_OPCODE_TEXT         0x1
40	#define WS_OPCODE_BINARY       0x2
41	#define WS_OPCODE_CLOSE        0x8
42	#define WS_OPCODE_PING         0x9
43	#define WS_OPCODE_PONG         0xa
44	
45	#define WS_FIN_BIT   0x80
46	#define WS_MASK_BIT  0x80
47	
48	/****************************************************************************
49	 * Private Functions - TLS
50	 ****************************************************************************/
51	
52	/* BIO send: write to the plain TCP fd. */
53	static int ws_bio_send(void *ctx, const unsigned char *buf, size_t len)
54	{
55	  int fd = *(int *)ctx;
56	  ssize_t ret = send(fd, buf, len, 0);
57	  if (ret < 0)
58	    {
59	      return -EIO;
60	    }
61	
62	  return (int)ret;
63	}
64	
65	/* BIO recv: read from the plain TCP fd. */
66	static int ws_bio_recv(void *ctx, unsigned char *buf, size_t len)
67	{
68	  int fd = *(int *)ctx;
69	  ssize_t ret = recv(fd, buf, len, 0);
70	  if (ret < 0)
71	    {
72	      return -EIO;
73	    }
74	
75	  if (ret == 0)
76	    {
77	      return MBEDTLS_ERR_SSL_WANT_READ;
78	    }
79	
80	  return (int)ret;
81	}
82	
83	static int ws_tls_init(struct xiaozhi_ws_s *ws)
84	{
85	  int ret;
86	
87	  mbedtls_ssl_init(&ws->ssl);
88	  mbedtls_ssl_config_init(&ws->conf);
89	  mbedtls_entropy_init(&ws->entropy);
90	  mbedtls_ctr_drbg_init(&ws->ctr_drbg);
91	
92	  ret = mbedtls_ctr_drbg_seed(&ws->ctr_drbg, mbedtls_entropy_func,
93	                              &ws->entropy,
94	                              (const unsigned char *)"xiaozhi", 7);
95	  if (ret != 0)
96	    {
97	      printf("[xiaozhi] drbg seed failed: -0x%x\n", -ret);
98	      return -EIO;
99	    }
100	
101	  ret = mbedtls_ssl_config_defaults(&ws->conf, MBEDTLS_SSL_IS_CLIENT,
102	                                    MBEDTLS_SSL_TRANSPORT_STREAM,
103	                                    MBEDTLS_SSL_PRESET_DEFAULT);
104	  if (ret != 0)
105	    {
106	      printf("[xiaozhi] ssl config defaults failed: -0x%x\n", -ret);
107	      return -EIO;
108	    }
109	
110	  /* Skip server cert verification for embedded use.
111	   * For production, configure CA certs via mbedtls_ssl_conf_ca_chain().
112	   */
113	  mbedtls_ssl_conf_authmode(&ws->conf, MBEDTLS_SSL_VERIFY_NONE);
114	  mbedtls_ssl_conf_rng(&ws->conf, mbedtls_ctr_drbg_random, &ws->ctr_drbg);
115	
116	  ret = mbedtls_ssl_setup(&ws->ssl, &ws->conf);
117	  if (ret != 0)
118	    {
119	      printf("[xiaozhi] ssl setup failed: -0x%x\n", -ret);
120	      return -EIO;
121	    }
122	
123	  return 0;
124	}
125	
126	/* Connect TCP, do TLS handshake over it. */
127	static int ws_tls_connect(struct xiaozhi_ws_s *ws, const char *host,
128	                         const char *port)
129	{
130	  struct hostent *he;
131	  struct sockaddr_in server;
132	  int portnum = atoi(port);
133	  int ret;
134	
135	  printf("[xiaozhi] TLS connecting to %s:%s\n", host, port);
136	
137	  he = gethostbyname(host);
138	  if (he == NULL)
139	    {
140	      printf("[xiaozhi] DNS resolve failed for %s\n", host);
141	      return -EIO;
142	    }
143	
144	  ws->fd = socket(AF_INET, SOCK_STREAM, 0);
145	  if (ws->fd < 0)
146	    {
147	      printf("[xiaozhi] socket() failed: %d\n", errno);
148	      return -EIO;
149	    }
150	
151	  memset(&server, 0, sizeof(server));
152	  server.sin_family = AF_INET;
153	  server.sin_port   = htons(portnum);
154	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
155	
156	  printf("[xiaozhi] TCP connect to %s:%d\n",
157	         inet_ntoa(server.sin_addr), portnum);
158	
159	  if (connect(ws->fd, (struct sockaddr *)&server, sizeof(server)) < 0)
160	    {
161	      printf("[xiaozhi] TCP connect failed: %d\n", errno);
162	      close(ws->fd);
163	      ws->fd = -1;
164	      return -EIO;
165	    }
166	
167	  printf("[xiaozhi] TCP connected, starting TLS handshake\n");
168	
169	  ret = mbedtls_ssl_set_hostname(&ws->ssl, host);
170	  if (ret != 0)
171	    {
172	      printf("[xiaozhi] set hostname failed: -0x%x\n", -ret);
173	      goto err;
174	    }
175	
176	  mbedtls_ssl_set_bio(&ws->ssl, &ws->fd, ws_bio_send, ws_bio_recv, NULL);
177	
178	  while ((ret = mbedtls_ssl_handshake(&ws->ssl)) != 0)
179	    {
180	      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
181	          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
182	        {
183	          printf("[xiaozhi] TLS handshake failed: -0x%x\n", -ret);
184	          goto err;
185	        }
186	    }
187	
188	  printf("[xiaozhi] TLS handshake complete\n");
189	  return 0;
190	
191	err:
192	  close(ws->fd);
193	  ws->fd = -1;
194	  return -EIO;
195	}
196	
197	/****************************************************************************
198	 * Private Functions - TLS read/write wrappers
199	 ****************************************************************************/
200	
201	/* Send all bytes over TLS. Returns 0 on success, -errno on failure. */
202	static int ws_tls_write_all(struct xiaozhi_ws_s *ws,
203	                            const uint8_t *buf, size_t len)
204	{
205	  size_t written = 0;
206	  while (written < len)
207	    {
208	      int ret = mbedtls_ssl_write(&ws->ssl, buf + written, len - written);
209	      if (ret == MBEDTLS_ERR_SSL_WANT_WRITE ||
210	          ret == MBEDTLS_ERR_SSL_WANT_READ)
211	        {
212	          continue;
213	        }
214	
215	      if (ret <= 0)
216	        {
217	          printf("[xiaozhi] tls write error: -0x%x\n", -ret);
218	          return -EIO;
219	        }
220	
221	      written += ret;
222	    }
223	
224	  return 0;
225	}
226	
227	/* Read exactly n bytes over TLS into buf. Returns 0 on success, -errno. */
228	static int ws_tls_read_all(struct xiaozhi_ws_s *ws, uint8_t *buf, size_t n)
229	{
230	  size_t got = 0;
231	  while (got < n)
232	    {
233	      int ret = mbedtls_ssl_read(&ws->ssl, buf + got, n - got);
234	      if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
235	          ret == MBEDTLS_ERR_SSL_WANT_WRITE)
236	        {
237	          continue;
238	        }
239	
240	      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
241	        {
242	          printf("[xiaozhi] tls peer closed during read\n");
243	          return -ECONNRESET;
244	        }
245	
246	      if (ret < 0)
247	        {
248	          printf("[xiaozhi] tls read error: -0x%x\n", -ret);
249	          return -EIO;
250	        }
251	
252	      got += ret;
253	    }
254	
255	  return 0;
256	}
257	
258	/****************************************************************************
259	 * Private Functions - WebSocket framing
260	 ****************************************************************************/
261	
262	/* Generate a random 4-byte masking key. mbedtls_ctr_drbg_random is used as
263	 * a random source (no Date.now/random needed).
264	 */
265	static void ws_make_mask(uint8_t mask[4], struct xiaozhi_ws_s *ws)
266	{
267	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, mask, 4);
268	}
269	
270	/* Send one client->server frame (masked). */
271	static int ws_send_frame(struct xiaozhi_ws_s *ws, uint8_t opcode,
272	                         const uint8_t *data, size_t len)
273	{
274	  uint8_t hdr[14];
275	  size_t hdrlen;
276	  uint8_t mask[4];
277	  int ret;
278	
279	  hdr[0] = WS_FIN_BIT | opcode;
280	
281	  if (len <= 125)
282	    {
283	      hdr[1] = WS_MASK_BIT | (uint8_t)len;
284	      hdrlen = 2;
285	    }
286	  else if (len <= 65535)
287	    {
288	      hdr[1] = WS_MASK_BIT | 126;
289	      hdr[2] = (len >> 8) & 0xff;
290	      hdr[3] = len & 0xff;
291	      hdrlen = 4;
292	    }
293	  else
294	    {
295	      /* 64-bit length path. Opus/JSON frames are never this large, but
296	       * implement for completeness.
297	       */
298	      hdr[1] = WS_MASK_BIT | 127;
299	      uint64_t l = len;
