/****************************************************************************
 * apps/examples/xiaozhi_voice/xiaozhi_mcp.c
 *
 * Minimal MCP (Model Context Protocol) server for the xiaozhi voice app.
 *
 * Implements the device (server) side of the xiaozhi MCP protocol: the cloud
 * (client) drives a JSON-RPC 2.0 conversation wrapped in {"type":"mcp",
 * "payload":{...}} frames. We answer three methods:
 *
 *   initialize   -> protocolVersion / capabilities / serverInfo
 *   tools/list   -> the tool(s) we expose
 *   tools/call   -> execute the named tool and return its result
 *
 * The only tool exposed is `self.app.start_lvgldemo`, which launches the
 * `lvgldemo` builtin. Because lvgldemo enters the LVGL event loop and does
 * not return, it is run on a detached worker thread so that replying to the
 * cloud (and the main recv loop) is not blocked.
 *
 * Reference: 78/xiaozhi-esp32 docs/mcp-protocol_zh.md, main/mcp_server.cc
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

#include <netutils/cJSON.h>

#include "xiaozhi_mcp.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define XIAOZHI_MCP_SERVER_NAME    "xiaozhi-voice"
#define XIAOZHI_MCP_SERVER_VERSION "1.0"
#define XIAOZHI_MCP_PROTOCOL_VER  "2024-11-05"

#define XIAOZHI_MCP_WORKER_STACK  32768

/* JSON-RPC error codes (subset of JSON-RPC 2.0 spec). */
#define JSONRPC_ERR_METHOD_NOT_FOUND  -32601
#define JSONRPC_ERR_INVALID_PARAMS    -32602
#define JSONRPC_ERR_INTERNAL          -32603

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Guards against launching lvgldemo twice. Volatile: touched from the
 * worker thread and the MCP handler (which runs on the main recv thread).
 */
static volatile bool g_lvgldemo_running;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Send a xiaozhi {"type":"mcp","payload":<payload>} text frame. */
static int send_mcp_frame(struct xiaozhi_ws_s *ws, const char *session_id,
                          cJSON *payload)
{
  cJSON *root = cJSON_CreateObject();
  if (root == NULL)
    {
      return -ENOMEM;
    }

  cJSON_AddStringToObject(root, "session_id", session_id);
  cJSON_AddStringToObject(root, "type", "mcp");
  cJSON_AddItemToObject(root, "payload", payload);

  char *json = cJSON_PrintUnformatted(root);
  cJSON_Delete(root);

  if (json == NULL)
    {
      return -ENOMEM;
    }

  int ret = xiaozhi_ws_send_text(ws, json, strlen(json));
  free(json);
  return ret;
}

/* Build a JSON-RPC success response: {"jsonrpc":"2.0","id":<id>,"result":<r>} */
static int reply_result(struct xiaozhi_ws_s *ws, const char *session_id,
                        int id, cJSON *result)
{
  cJSON *payload = cJSON_CreateObject();
  cJSON_AddStringToObject(payload, "jsonrpc", "2.0");
  cJSON_AddNumberToObject(payload, "id", id);
  cJSON_AddItemToObject(payload, "result", result);
  return send_mcp_frame(ws, session_id, payload);
}

/* Build a JSON-RPC error response. */
static int reply_error(struct xiaozhi_ws_s *ws, const char *session_id,
                       int id, int code, const char *message)
{
  cJSON *payload = cJSON_CreateObject();
  cJSON *error    = cJSON_CreateObject();

  cJSON_AddStringToObject(payload, "jsonrpc", "2.0");
  cJSON_AddNumberToObject(payload, "id", id);
  cJSON_AddItemToObject(payload, "error", error);
  cJSON_AddNumberToObject(error, "code", code);
  cJSON_AddStringToObject(error, "message", message);

  return send_mcp_frame(ws, session_id, payload);
}

/* Build a tools/call text content result:
 * {"content":[{"type":"text","text":<text>}],"isError":<iserr>} */
static cJSON *make_text_result(const char *text, bool iserr)
{
  cJSON *result  = cJSON_CreateObject();
  cJSON *content = cJSON_CreateArray();
  cJSON *item    = cJSON_CreateObject();

  cJSON_AddItemToObject(result, "content", content);
  cJSON_AddItemToArray(content, item);
  cJSON_AddStringToObject(item, "type", "text");
  cJSON_AddStringToObject(item, "text", text);
  cJSON_AddBoolToObject(result, "isError", iserr);

  return result;
}

/* Worker thread: run lvgldemo via system(). lvgldemo blocks in the LVGL
 * event loop; this thread stays alive until the demo exits. */
static void *lvgldemo_worker(void *arg)
{
  (void)arg;

  printf("[xiaozhi] mcp: launching lvgldemo\n");
  int rc = system("lvgldemo");
  printf("[xiaozhi] mcp: lvgldemo exited (rc=%d)\n", rc);

  g_lvgldemo_running = false;
  return NULL;
}

/* Launch lvgldemo on a detached thread. Returns 0 if launched, -EEXIST if
 * already running. */
static int launch_lvgldemo(void)
{
  if (g_lvgldemo_running)
    {
      return -EEXIST;
    }

  pthread_attr_t attr;
  pthread_t tid;
  int ret;

  ret = pthread_attr_init(&attr);
  if (ret != 0)
    {
      return -ret;
    }

  pthread_attr_setstacksize(&attr, XIAOZHI_MCP_WORKER_STACK);
  pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

  g_lvgldemo_running = true;
  ret = pthread_create(&tid, &attr, lvgldemo_worker, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      g_lvgldemo_running = false;
      return -ret;
    }

  return 0;
}

/* Build the single tool description used in tools/list. */
static cJSON *make_tool_descriptor(void)
{
  cJSON *tool        = cJSON_CreateObject();
  cJSON *input_schema = cJSON_CreateObject();
  cJSON *properties  = cJSON_CreateObject();

  cJSON_AddStringToObject(tool, "name", XIAOZHI_MCP_TOOL_LVGLDEMO);
  cJSON_AddStringToObject(tool, "description",
                           "Start the LVGL demo application on the device.");
  cJSON_AddItemToObject(tool, "inputSchema", input_schema);
  cJSON_AddStringToObject(input_schema, "type", "object");
  cJSON_AddItemToObject(input_schema, "properties", properties);

  return tool;
}

/* Handle tools/call. Returns 0 after sending a response. */
static int handle_tools_call(struct xiaozhi_ws_s *ws, const char *session_id,
                             int id, cJSON *params)
{
  if (!cJSON_IsObject(params))
    {
      return reply_error(ws, session_id, id, JSONRPC_ERR_INVALID_PARAMS,
                         "Missing params");
    }

  cJSON *name = cJSON_GetObjectItem(params, "name");
  if (!cJSON_IsString(name))
    {
      return reply_error(ws, session_id, id, JSONRPC_ERR_INVALID_PARAMS,
                         "Missing tool name");
    }

  if (strcmp(name->valuestring, XIAOZHI_MCP_TOOL_LVGLDEMO) != 0)
    {
      char msg[96];
      snprintf(msg, sizeof(msg), "Unknown tool: %s", name->valuestring);
      return reply_error(ws, session_id, id, JSONRPC_ERR_METHOD_NOT_FOUND,
                         msg);
    }

  int ret = launch_lvgldemo();
  if (ret == -EEXIST)
    {
      return reply_result(ws, session_id, id,
                          make_text_result("already running", false));
    }

  if (ret != 0)
    {
      char msg[96];
      snprintf(msg, sizeof(msg), "Failed to launch lvgldemo: %d", ret);
      return reply_error(ws, session_id, id, JSONRPC_ERR_INTERNAL, msg);
    }

  return reply_result(ws, session_id, id,
                      make_text_result("true", false));
}

/* Handle tools/list. */
static int handle_tools_list(struct xiaozhi_ws_s *ws, const char *session_id,
                             int id)
{
  cJSON *result = cJSON_CreateObject();
  cJSON *tools  = cJSON_CreateArray();

  cJSON_AddItemToObject(result, "tools", tools);
  cJSON_AddItemToArray(tools, make_tool_descriptor());

  return reply_result(ws, session_id, id, result);
}

/* Handle initialize. */
static int handle_initialize(struct xiaozhi_ws_s *ws, const char *session_id,
                             int id)
{
  cJSON *result       = cJSON_CreateObject();
  cJSON *capabilities = cJSON_CreateObject();
  cJSON *server_info  = cJSON_CreateObject();

  cJSON_AddStringToObject(result, "protocolVersion",
                          XIAOZHI_MCP_PROTOCOL_VER);
  cJSON_AddItemToObject(result, "capabilities", capabilities);
  cJSON_AddItemToObject(capabilities, "tools", cJSON_CreateObject());
  cJSON_AddItemToObject(result, "serverInfo", server_info);
  cJSON_AddStringToObject(server_info, "name", XIAOZHI_MCP_SERVER_NAME);
  cJSON_AddStringToObject(server_info, "version",
                          XIAOZHI_MCP_SERVER_VERSION);

  return reply_result(ws, session_id, id, result);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int xiaozhi_mcp_handle_message(struct xiaozhi_ws_s *ws,
                               const char *session_id,
                               cJSON *payload)
{
  cJSON *method = cJSON_GetObjectItem(payload, "method");
  cJSON *id     = cJSON_GetObjectItem(payload, "id");
  cJSON *params = cJSON_GetObjectItem(payload, "params");
  int id_int = cJSON_IsNumber(id) ? id->valueint : 0;

  if (!cJSON_IsString(method))
    {
      return reply_error(ws, session_id, id_int, JSONRPC_ERR_INVALID_PARAMS,
                         "Missing method");
    }

  const char *m = method->valuestring;
  printf("[xiaozhi] mcp: method=%s id=%d\n", m, id_int);

  if (strcmp(m, "initialize") == 0)
    {
      return handle_initialize(ws, session_id, id_int);
    }

  if (strcmp(m, "tools/list") == 0)
    {
      return handle_tools_list(ws, session_id, id_int);
    }

  if (strcmp(m, "tools/call") == 0)
    {
      return handle_tools_call(ws, session_id, id_int, params);
    }

  /* Notifications (no id) are not answered; everything else is an error. */
  if (cJSON_IsNumber(id))
    {
      char msg[96];
      snprintf(msg, sizeof(msg), "Method not implemented: %s", m);
      return reply_error(ws, session_id, id_int,
                         JSONRPC_ERR_METHOD_NOT_FOUND, msg);
    }

  return 0;
}

void xiaozhi_mcp_add_features(cJSON *features)
{
  if (features != NULL)
    {
      cJSON_AddBoolToObject(features, "mcp", true);
    }
}

